import{_ as l,c as t,o as i,ae as e}from"./chunks/framework.CDAOyxyO.js";const c=JSON.parse('{"title":"Релизы","description":"","frontmatter":{},"headers":[],"relativePath":"projects/alt-domain/admc/releases/index.md","filePath":"projects/alt-domain/admc/releases/index.md"}'),o={name:"projects/alt-domain/admc/releases/index.md"};function r(u,a,n,s,h,d){return i(),t("div",null,a[0]||(a[0]=[e('<h1 id="релизы" tabindex="-1">Релизы <a class="header-anchor" href="#релизы" aria-label="Permalink to &quot;Релизы&quot;">​</a></h1><h2 id="_0-20-0-alt2" tabindex="-1">0.20.0-alt2 <a class="header-anchor" href="#_0-20-0-alt2" aria-label="Permalink to &quot;0.20.0-alt2&quot;">​</a></h2><p><strong>Дата выпуска</strong>: 08.04.2025 г.</p><ul><li>CMake получил своё обновление!</li></ul><h2 id="_0-20-0-alt1" tabindex="-1">0.20.0-alt1 <a class="header-anchor" href="#_0-20-0-alt1" aria-label="Permalink to &quot;0.20.0-alt1&quot;">​</a></h2><p><strong>Дата выпуска</strong>: 17.03.2025 г.</p><ul><li>Реализована нативная поддержка LAPS (Local Administrator Password Solution) 2023. Соответствующая вкладка была добавлена в свойства объектов класса &quot;Компьютер&quot;, где включено использование LAPS.</li></ul><h2 id="_0-19-0-alt1" tabindex="-1">0.19.0-alt1 <a class="header-anchor" href="#_0-19-0-alt1" aria-label="Permalink to &quot;0.19.0-alt1&quot;">​</a></h2><p><strong>Дата выпуска</strong>: 04.03.2025 г.</p><h3 id="новые-функции" tabindex="-1">Новые функции: <a class="header-anchor" href="#новые-функции" aria-label="Permalink to &quot;Новые функции:&quot;">​</a></h3><ol><li>Безопасность <ul><li>Добавлено действие &quot;Показать дескриптор в формате SDDL&quot; в меню &quot;Дополнительно&quot; на вкладке безопасности. Позволяет отображать дескриптор безопасности в формате SDDL.</li><li>Реализована возможность отката ранее примененного дескриптора безопасности. Действие &quot;Откат к предыдущему дескриптору&quot; доступно в меню &quot;Дополнительно&quot; на вкладке безопасности.</li></ul></li><li>Производительность <ul><li>Существенно сокращена задержка при взаимодействии с объектами групповой политики в древовидном представлении.</li></ul></li><li>Создание пользователей <ul><li>Добавлена возможность указания отчества при создании пользователя. Поле отчества может быть отображено через меню &quot;Настройки&quot; → &quot;Показывать отчество при создании&quot;.</li></ul></li><li>Работа с атрибутами <ul><li>Добавлена возможность копирования значений отображаемых атрибутов.</li></ul></li></ol><h3 id="исправления-ошибок" tabindex="-1">Исправления ошибок: <a class="header-anchor" href="#исправления-ошибок" aria-label="Permalink to &quot;Исправления ошибок:&quot;">​</a></h3><ol><li>Интерфейс <ul><li>Исправлены ошибки в журнале изменений (changelog) (issue #45839).</li></ul></li><li>Атрибуты <ul><li>Устранена проблема исчезновения необязательных атрибутов после действия &quot;Сброс&quot; на вкладке атрибутов.</li><li>Исправлено отображение необязательных атрибутов msDS-User-Account-Control-Computed и msDS-User-Password-Expire-Time-Computed.</li></ul></li></ol><h2 id="_0-18-0-alt1" tabindex="-1">0.18.0-alt1 <a class="header-anchor" href="#_0-18-0-alt1" aria-label="Permalink to &quot;0.18.0-alt1&quot;">​</a></h2><p><strong>Дата выпуска</strong>: 05.12.2024 г.</p><h3 id="новые-функции-1" tabindex="-1">Новые функции: <a class="header-anchor" href="#новые-функции-1" aria-label="Permalink to &quot;Новые функции:&quot;">​</a></h3><ol><li>Вкладка безопасности <ul><li>Добавлены настраиваемые разрешения: создание/удаление дочерних объектов и чтение/запись свойств.</li><li>Добавлены задачи делегирования в вкладку безопасности. Эти задачи соответствуют стандартным задачам из диалога делегирования RSAT.</li><li>Расширенные права помещены в отдельную вкладку &quot;Разрешения&quot;.</li><li>Общие и стандартные разрешения находятся во вкладке &quot;Общие разрешения&quot;. К ним добавлены следующие возможности: просмотр содержимого, чтение/запись всех свойств, удаление, удаление поддерева, чтение разрешений, изменение разрешений, изменение владельца, все проверяемые записи и все расширенные права.</li></ul></li><li>Область применения разрешений <ul><li>Добавлена возможность выбора области действия разрешений в вкладке безопасности. Соответствующие разрешения могут быть применены к целевому объекту, целевому объекту и дочерним объектам, только к дочерним объектам или к дочерним объектам определенного класса. Задачи делегирования применяются только к целевому объекту.</li></ul></li><li>Поведение снятия разрешений <ul><li>Изменено поведение снятия разрешений: снятие более высокого разрешения автоматически снимает все зависимые разрешения. Например, снятие разрешения &quot;Полный контроль&quot; снимает все остальные разрешения.</li></ul></li><li>Вкладка ссылок (OU политики) <ul><li>Добавлены действия &quot;Установить/снять все&quot; и &quot;Редактировать&quot; во вкладке ссылок виджета OU политики. <ul><li>Действие &quot;Установить/снять все&quot; устанавливает или снимает состояние (принудительно/отключено, в зависимости от столбца) для всех связанных политик.</li><li>Действие &quot;Редактировать&quot; открывает интерфейс редактирования групповой политики (GPUI). Эти действия можно вызывать через контекстное меню.</li></ul></li></ul></li></ol><h3 id="исправления-ошибок-1" tabindex="-1">Исправления ошибок: <a class="header-anchor" href="#исправления-ошибок-1" aria-label="Permalink to &quot;Исправления ошибок:&quot;">​</a></h3><ol><li>Тестирование <ul><li>Исправлены сбои тестов, вызванные случайным выбором недопустимого доменного контроллера.</li></ul></li></ol><h2 id="_0-17-2-alt1" tabindex="-1">0.17.2-alt1 <a class="header-anchor" href="#_0-17-2-alt1" aria-label="Permalink to &quot;0.17.2-alt1&quot;">​</a></h2><p><strong>Дата выпуска</strong>: 05.12.2024 г.</p><h3 id="исправления-ошибок-2" tabindex="-1">Исправления ошибок: <a class="header-anchor" href="#исправления-ошибок-2" aria-label="Permalink to &quot;Исправления ошибок:&quot;">​</a></h3><ul><li>Устранена проблема потери информации о сайте и доменном контроллере в виджете сведений о домене (для дочерних доменов)(Решена задача: <a href="https://bugzilla.altlinux.org/52329" target="_blank" rel="noreferrer">#52329 - Центр управления Active Directory не отображает полностью информацию о домене</a>)</li></ul><h2 id="_0-17-1-alt1" tabindex="-1">0.17.1-alt1 <a class="header-anchor" href="#_0-17-1-alt1" aria-label="Permalink to &quot;0.17.1-alt1&quot;">​</a></h2><p><strong>Дата выпуска</strong>: 06.11.2024 г.</p><h3 id="исправления-ошибок-3" tabindex="-1">Исправления ошибок: <a class="header-anchor" href="#исправления-ошибок-3" aria-label="Permalink to &quot;Исправления ошибок:&quot;">​</a></h3><ul><li>Устранена ошибка, приводившая к аварийному завершению работы программы при запросе контекстного меню в дочерних доменах.</li></ul><h2 id="_0-17-0-alt1" tabindex="-1">0.17.0-alt1 <a class="header-anchor" href="#_0-17-0-alt1" aria-label="Permalink to &quot;0.17.0-alt1&quot;">​</a></h2><p><strong>Дата выпуска</strong>: 21.08.2024 г.</p><h3 id="новые-функции-2" tabindex="-1">Новые функции: <a class="header-anchor" href="#новые-функции-2" aria-label="Permalink to &quot;Новые функции:&quot;">​</a></h3><ul><li>Добавлена возможность создания, удаления и редактирования объектов настроек паролей (Password Settings Object). Контейнер настроек паролей находится в контейнере System (System container) в дереве объектов и содержит эти объекты.</li><li>Добавлена возможность просмотра списка групп, в которых является членом выбранная группа.</li></ul><h3 id="исправления-ошибок-4" tabindex="-1">Исправления ошибок: <a class="header-anchor" href="#исправления-ошибок-4" aria-label="Permalink to &quot;Исправления ошибок:&quot;">​</a></h3><ul><li>Исправлено отображение пустых скобок в виджете информации о домене при неопределенной версии доменного контроллера.</li></ul><h2 id="дозаполнять" tabindex="-1">Дозаполнять! <a class="header-anchor" href="#дозаполнять" aria-label="Permalink to &quot;Дозаполнять!&quot;">​</a></h2>',34)]))}const m=l(o,[["render",r]]);export{c as __pageData,m as default};
